      <template v-if="active==='settings'">
        <div class="two-columns"><article class="panel"><h3>服务运行状态</h3><dl class="service-list"><div><dt>前端工作台</dt><dd>Vue 3 · Vite</dd></div><div><dt>业务 API</dt><dd><i class="online-dot"></i> FastAPI · {{ health?.status }}</dd></div><div><dt>工作主档与修改日志</dt><dd>SQLite · 持久化</dd></div><div><dt>查询缓存</dt><dd>{{ health?.redis }}</dd></div><div><dt>运行模式</dt><dd>{{ health?.mode }}</dd></div></dl><div class="toolbar-actions"><a class="button white" href="/docs" target="_blank" rel="noopener">OpenAPI 文档 <ExternalLink :size="14"/></a><a class="button white" href="/metrics" target="_blank" rel="noopener">Prometheus 指标 <ExternalLink :size="14"/></a></div></article><article class="panel"><h3>数据使用说明</h3><p class="muted spaced">ERP订单、成本与利润来自可复现模拟数据。公开商品保留采集时点信息，展示销量属于代理指标。问卷汇总基于243份用户确认的真实回收。</p><p class="muted">商品维护在独立工作主档中生效，不回写原始采集文件。当前平台用于本地单用户操作；容器部署提供 Nginx、Redis 和 Prometheus 配套服务。</p><span class="badge">原始数据与工作修改分层保存</span></article></div>
        <article class="panel table-panel"><div class="panel-heading"><div><h3>数据来源清单</h3><p>明确每一项结论使用了什么证据</p></div></div><DataTable :rows="rows('evidence')" :columns="[{key:'source',label:'来源',class:'primary-cell'},{key:'scope',label:'范围'},{key:'record_count',label:'记录数',type:'number'},{key:'data_nature',label:'数据性质'},{key:'decision_use',label:'决策用途'}]"/></article>
        <article class="panel table-panel"><div class="panel-heading"><h3>商品主数据字段字典</h3><span class="badge gray">19项字段</span></div><DataTable :rows="rows('dictionary')" :columns="[{key:'field_name',label:'字段',class:'mono'},{key:'field_name_cn',label:'名称'},{key:'business_definition',label:'业务含义',class:'wide-cell'},{key:'validation_rule',label:'校验规则',class:'wide-cell'}]"/></article>
      </template>
      <footer class="site-footer"><span>ARKNIGHTS ANALYTICS <i> / </i> IP周边选品与商品运营分析平台</span><a href="https://github.com/lubdbdbd/ArknightsAnalytics" target="_blank" rel="noopener">开源项目 · lubdbdbd <ArrowUpRight :size="13"/></a></footer>
    </div>
