  <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="18"/>{{ toast }}</div>
  <div v-if="editing" class="modal-backdrop" @click.self="!saving&&(editing=null)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title"><header><div><span class="eyebrow">PRODUCT MAINTENANCE</span><h2 id="edit-title">维护商品信息</h2><p>{{ editing.entity_id }} · 版本 {{ editing.version }}</p></div><button class="icon-btn" @click="editing=null" :disabled="saving" aria-label="关闭"><X/></button></header><form @submit.prevent="saveEdit"><div class="form-grid"><template v-if="domain==='internal'"><label class="full">商品名称<input v-model="editForm.product_name" required/></label><label>供应商编码<input v-model="editForm.supplier_id" required/></label><label>生命周期<select v-model="editForm.sku_status"><option value="active">在售</option><option value="planned">规划中</option><option value="inactive">停售</option></select></label><label>售价（元）<input type="number" step="0.01" min="0.01" v-model.number="editForm.price" required/></label><label>单位成本（元）<input type="number" step="0.01" min="0" v-model.number="editForm.unit_cost" required/></label><label>安全库存<input type="number" step="1" min="0" v-model.number="editForm.safety_stock" required/></label><label>再订货点<input type="number" step="1" min="0" v-model.number="editForm.reorder_point" required/></label><label>采购提前期（天）<input type="number" step="1" min="0" v-model.number="editForm.purchase_lead_time_days" required/></label></template><template v-else><label class="full">商品标题<textarea v-model="editForm.product_title" rows="2" required/></label><label>关联角色<input v-model="editForm.operator" required/></label><label>标准品类<select v-model="editForm.category"><option v-for="item in [...(health?.categories||[]),'其他正版周边']" :key="item">{{ item }}</option></select></label><label>公开展示价格<input type="number" step="0.01" min="0.01" v-model.number="editForm.list_price" required/></label><label>履约类型<select v-model="editForm.fulfillment_type"><option>未标明</option><option>现货/在售</option><option>预售</option><option>补款</option></select></label><label>人工授权核验<select v-model="editForm.verification_status"><option value="pending">待核验</option><option value="verified">已核验</option><option value="rejected">已驳回</option></select></label><label>证据链接<input v-model="editForm.evidence_url" type="url" placeholder="https://…" :required="editForm.verification_status!=='pending'"/></label><a class="source-link full" :href="editing.source_url" target="_blank" rel="noopener">查看原始商品页面 <ExternalLink :size="14"/></a><p class="full muted">{{ editing.maintenance_action }}</p></template><label class="full">修改原因<textarea v-model="reason" minlength="3" maxlength="500" rows="2" placeholder="说明本次修改的依据，至少3个字" required/></label></div><div v-if="modalError" class="error-banner" role="alert">{{ modalError }}</div><div class="form-footer"><span>已记录 {{ auditRows.length }} 次人工修改</span><button class="button primary" :disabled="saving">{{ saving?'保存中…':'保存并记录变更' }}</button></div></form></section></div>
  <div v-if="showAudit" class="modal-backdrop" @click.self="showAudit=false"><section class="modal wide" role="dialog" aria-modal="true" aria-label="商品修改日志"><header><div><span class="eyebrow">AUDIT TRAIL</span><h2>商品修改日志</h2><p>仅展示真实操作产生的记录</p></div><button class="icon-btn" @click="showAudit=false" aria-label="关闭"><X/></button></header><div class="audit-list"><article v-for="row in auditRows" :key="row.audit_id"><div><b>{{ row.entity_id }}</b><span class="badge gray">v{{ row.version }}</span><time>{{ new Date(row.changed_at).toLocaleString('zh-CN') }}</time></div><p>{{ row.reason }}</p><dl><div v-for="(value,key) in JSON.parse(row.after_json)" :key="key"><dt>{{ key }}</dt><dd><del>{{ JSON.parse(row.before_json)[key] }}</del><ArrowRight :size="12"/><strong>{{ value }}</strong></dd></div></dl></article><p v-if="!auditRows.length" class="empty">还没有人工修改。保存商品后，会在这里记录修改前后值、原因与时间。</p></div></section></div>
  <div v-if="showImport" class="modal-backdrop" @click.self="!importing&&(showImport=false)"><section class="modal wide" role="dialog" aria-modal="true" aria-label="CSV批量维护"><header><div><span class="eyebrow">BATCH MAINTENANCE</span><h2>CSV 批量维护</h2><p>先预览校验，再逐条保存有效记录；最多500条</p></div><button class="icon-btn" @click="showImport=false" :disabled="importing" aria-label="关闭"><X/></button></header><p class="muted">第一列使用 sku_code，其他列支持 price、unit_cost、supplier_id、product_name、safety_stock、reorder_point、purchase_lead_time_days、sku_status。只保留要修改的列。</p><pre class="csv-example">sku_code,price,unit_cost
AK-0001,48,16.8</pre><label class="upload-zone"><Upload :size="23"/><span>选择 UTF-8 CSV 文件进行校验</span><input type="file" accept=".csv" @change="previewFile" :disabled="importing"/></label><div v-if="modalError" class="error-banner">{{ modalError }}</div><template v-if="importRows"><p>已检查 {{ importRows.total }} 条，{{ importRows.valid_count }} 条可保存。</p><DataTable :rows="importRows.items.map(row=>({...row,status:row.valid?'校验通过':row.error}))" :columns="[{key:'line',label:'行号'},{key:'sku_code',label:'SKU编码'},{key:'status',label:'校验结果',class:'wide-cell'}]"/><div class="form-footer"><span>无效行不会保存；发生版本冲突时停止后续操作。</span><button class="button primary" :disabled="importing||!importRows.valid_count" @click="applyImport">{{ importing?'保存中…':'保存有效记录' }}</button></div></template></section></div>
  <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal wide" role="dialog" aria-modal="true" aria-label="订单明细"><header><div><span class="eyebrow">ORDER RECONCILIATION</span><h2>{{ detail.order_id }}</h2><p>{{ detail.channel }} · {{ detail.order_date }} · 模拟ERP</p></div><button class="icon-btn" @click="detail=null" aria-label="关闭"><X/></button></header><div class="section-notice">实付 {{ exactMoney(detail.paid_amount) }} ｜商品额 {{ exactMoney(detail.order_amount) }} − 优惠 {{ exactMoney(detail.discount_amount) }} + 运费 {{ exactMoney(detail.shipping_fee) }}{{ detail.payment_status==='cancelled'?'（已取消订单，预期实付为0）':'' }}</div><p v-if="detailLoading" class="empty">正在加载订单明细…</p><DataTable v-else :rows="detailRows" :columns="[{key:'sku_id',label:'商品',class:'primary-cell'},{key:'quantity',label:'数量',type:'number'},{key:'unit_price',label:'单价',type:'money'},{key:'discount_amount',label:'优惠',type:'money'},{key:'net_revenue',label:'净收入',type:'money'}]"/></section></div>
  <div v-if="showHelp" class="modal-backdrop" @click.self="showHelp=false"><section class="modal" role="dialog" aria-modal="true" aria-label="使用说明"><header><h2>开始使用运营工作台</h2><button class="icon-btn" @click="showHelp=false" aria-label="关闭"><X/></button></header><ol class="help-list"><li>在“商品信息维护”搜索SKU，修改价格与库存策略，填写依据后保存。</li><li>在“公开商品档案”补充角色、履约和授权证据，在修改日志核对操作。</li><li>在“ERP数据处理”查询订单明细，检查库存分群、补货计划和售后原因。</li><li>在“周边用户调研”比较角色、品类、价格带与购买阻力，再到“角色与选品”查看多源证据。</li></ol><p class="muted">各模块可导出CSV，便于在Excel中进一步分析。</p></section></div>
</div>
</template>
